///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.movePage
 * @author Inswave
 * @date 2026. 09. 29
 * @param id curSh
 * @returns
 * @hidden N
*/
scwin.movePage = function (id, curSh) {
    /* sdd-asis-lifecycle:begin movePage — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    ((($c.data.getParameter() && typeof $c.data.getParameter() === 'object' && Object.keys($c.data.getParameter()).length) ? $c.data.getParameter() : (((($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null) || {}).scwin || {})).parent).downMenuLink(id, curSh, "03");
    $c.win.closePopup();
    /* sdd-asis-lifecycle:end */
};
